import re
from auto_config.generator.bts.bts import BTS
from auto_config.generator.utils.utils import is_type_sa, is_type_sa_nsa
from auto_config.generator.vcu.params_generator_factory import ParamsGeneratorFactory


class VCU(BTS):

    def get_params_generator_factory(self):
        return ParamsGeneratorFactory()

    def add_specific_mocs(self, dist_names, enb_ent_config, execution_config):
        pass

    def update_managed_object_occurrences(self, vcu_ent_config, execution_config, pddb_topology, epc_config):
        occurrences = {
            # CP
            'BWP_PROFILE': 4,
            'NRBTS': 1,
            'NRCELL': vcu_ent_config['cells_count'],
            'NRCELLGRP': vcu_ent_config['cells_count'],
            'NRCTRLTS': 1 if is_type_sa_nsa(vcu_ent_config) else 0,
            'NRMTRACECU': 1 if is_type_sa_nsa(vcu_ent_config) else 0,
            'NRDRB': 15,
            'NRDRB_5QI': 6,
            'NRDRB_PDCP': 3,
            'NRDRB_QCI': 8 if is_type_sa_nsa(vcu_ent_config) else 0,
            'NRDRX': 7 if is_type_sa(vcu_ent_config) else 5,
            'NRDU': vcu_ent_config['radios_count'],
            # 'NRDU_SNSSAI': 1,
            'NRHOIF': 1 if is_type_sa(vcu_ent_config) else 0,
            'NRPLMN': 1,
            'NRSYSINFO_PROFILE': 1,
            'NRIAFIM': 1,
            'NRIRFIM': 1 if is_type_sa_nsa(vcu_ent_config) else 0,
            'NRLIM': 1 if is_type_sa_nsa(vcu_ent_config) else 0,
            'NRMEASCFG_IF': 1 if is_type_sa(vcu_ent_config) else 0,
            'NRMOPR_SA': 1 if is_type_sa(vcu_ent_config) else 0,
            'NRPRIOACC_PROFILE': 1 if is_type_sa(vcu_ent_config) else 0,
            'SERVEDAMF': 1,
            # 'NRPLMN_SUPPORT': 1,
            'SNSSAI': 1,

            # MANAGEMENT
            'CMD': 1,
            'PMMNL': 1,
            'TEST': 1,
            'TCEADM': 1 if is_type_sa_nsa(vcu_ent_config) else 0,
            'TCE': 1 if is_type_sa_nsa(vcu_ent_config) else 0,

            # TRANSPORT
            'TNL': 6,
            'ETHSVC': 1,
            'ETHIF': 1,
            'ETHLK': 1,
            'IPAPP': [1, 1, 0, 1, 1, 0] if is_type_sa_nsa(vcu_ent_config) else 0,
            'IPIF': [1, 4, 4, 1, 4, 4] if is_type_sa_nsa(vcu_ent_config) else [1, 3, 3, 1, 3, 3],
            'VLANIF': [1, 4, 4, 1, 4, 4] if is_type_sa_nsa(vcu_ent_config) else [1, 3, 3, 1, 3, 3],
            'TNLTEMPLATE': 3,
        }

        if vcu_ent_config['cells_count_fdd'] > 0:
            occurrences['NRCELL_FDD'] = 1

        if vcu_ent_config['is_ipv4']:
            occurrences['IPADDRESSV4'] = 1

        if vcu_ent_config['is_ipv6']:
            occurrences['IPADDRESSV6'] = 1

        self.update_nrrel_managed_objects(occurrences, vcu_ent_config)
        self.update_nradjgnb_managed_objects(occurrences, vcu_ent_config)
        self.update_xnlink_managed_objects(occurrences, vcu_ent_config)
        self.update_nradjnrcell_managed_objects(occurrences, vcu_ent_config)
        self.update_amf_managed_objects(occurrences, epc_config)
        if vcu_ent_config.get("tnl_conf"):
            self.update_ipif_vlanif_managed_objects(occurrences, vcu_ent_config)

        for mo_name, occurrences in occurrences.items():
            pddb_topology[mo_name]['mo_min_occurs'] = occurrences

    def update_starting_index(self, enb_ent_config, pddb_params, pddb_topology):

        def set_starting_index(mo_name, starting_index_value):
            # nonlocal pddb_params, pddb_topology
            index_name = pddb_topology[mo_name]['index']
            pddb_params[mo_name][index_name]['range'] = starting_index_value

        set_starting_index('NRBTS', enb_ent_config['id'])
        set_starting_index('NRCELL', 1)
        set_starting_index('NRCELLGRP', 1)
        set_starting_index('NRSYSINFO_PROFILE', 1)
        set_starting_index('TRACKINGAREA', 1)

    @staticmethod
    def update_nrrel_managed_objects(occurrences, vcu_ent_config):
        cells = vcu_ent_config['cells'].values()
        nrrel_occurrences_list = [len(cell['nrrel']) if 'nrrel' in cell else 0 for cell in cells]
        occurrences.update({'NRREL': nrrel_occurrences_list})

    @staticmethod
    def update_nradjgnb_managed_objects(occurrences, vcu_ent_config):
        if 'nradjgnb' in vcu_ent_config:
            occurrences.update({'NRADJGNB': len(vcu_ent_config['nradjgnb'])})

    @staticmethod
    def update_xnlink_managed_objects(occurrences, vcu_ent_config):
        if 'xnlink' in vcu_ent_config:
            occurrences.update({'XNLINK': len(vcu_ent_config['xnlink'])})

    @staticmethod
    def update_nradjnrcell_managed_objects(occurrences, vcu_ent_config):
        if 'nradjnrcell' in vcu_ent_config:
            occurrences.update({'NRADJNRCELL': len(vcu_ent_config['nradjnrcell'])})

    @staticmethod
    def update_amf_managed_objects(occurrences, epc_config):
        num = 0
        for key in epc_config.keys():
            if re.search(r'^amf', key):
                num += 1
        if num > 0:
            occurrences['SERVEDAMF'] = num

    @staticmethod
    def update_ipif_vlanif_managed_objects(occurrences, vcu_ent_config):
        updated_list = occurrences['IPIF'].copy()
        for index, occurence in enumerate(occurrences['IPIF'], 1):
            custom_ipif_occurence = set()
            tnl_found = False
            for dn in vcu_ent_config['tnl_conf'].values():
                srch = re.search(r"TNL-(\d+)/IPNO-1/IPIF-(\d+)", dn)
                tnl_num = srch.group(1)
                ipif_num = srch.group(2)
                if int(index) == int(tnl_num):
                    tnl_found = True
                    custom_ipif_occurence.add(ipif_num)
            if tnl_found:
                updated_list[index - 1] = len(custom_ipif_occurence)
        occurrences['IPIF'] = list(updated_list)
        occurrences['VLANIF'] = list(updated_list)
